using DSAExperimentation.DataStructures.SinglyLinkedList;
namespace DSAExperimentation.Tests.LeetCodeCoverage.InsertionSortList;
public sealed partial class InsertionSortListTests { [Fact] public void InsertionSortList_Example_SortsNodes(){Assert.Equal([1,2,3,4],ToArray(Sort(Build([4,2,1,3]))));} private static SinglyLinkedListNode<int>? Sort(SinglyLinkedListNode<int>? head){var d=new SinglyLinkedListNode<int>(0);for(var node=head;node is not null;){var next=node.Next;var p=d;while(p.Next is not null&&p.Next.Value<node.Value)p=p.Next;node.Next=p.Next;p.Next=node;node=next;}return d.Next;} private static SinglyLinkedListNode<int>? Build(int[] a){var d=new SinglyLinkedListNode<int>(0);var t=d;foreach(var v in a){t.Next=new SinglyLinkedListNode<int>(v);t=t.Next;}return d.Next;} private static int[] ToArray(SinglyLinkedListNode<int>? h){var r=new List<int>();for(var n=h;n is not null;n=n.Next)r.Add(n.Value);return r.ToArray();} }
